1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>落点 · 选址对比决策台</title>
7	<style>
8	  :root{
9	    --bg:#f4f2ed; --card:#ffffff; --ink:#1d2433; --muted:#6b7280; --line:#e7e2d8;
10	    --accent:#b45309; --good:#047857; --mapbg:#0c1424;
11	  }
12	  *{box-sizing:border-box}
13	  html,body{margin:0;padding:0}
14	  body{
15	    background:var(--bg); color:var(--ink);
16	    font:14px/1.45 -apple-system,"Segoe UI","Microsoft YaHei",system-ui,sans-serif;
17	  }
18	  .app{max-width:1480px;margin:0 auto;padding:14px 18px 18px;}
19	
20	  /* ---------- header ---------- */
21	  header{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;padding:4px 2px 12px;}
22	  h1{font-size:21px;margin:0;letter-spacing:.5px;}
23	  h1 em{font-style:normal;color:var(--accent);}
24	  .sub{margin:3px 0 0;color:var(--muted);font-size:12.5px;}
25	  .h-right{display:flex;align-items:center;gap:12px;}
26	  #cmpCount{font-size:12px;color:var(--muted);border:1px solid var(--line);background:#fff;border-radius:999px;padding:4px 12px;white-space:nowrap;}
27	  #refreshBtn{font-size:12.5px;border:1px solid var(--accent);color:var(--accent);background:#fff;border-radius:8px;padding:5px 12px;cursor:pointer;}
28	  #refreshBtn:hover{background:var(--accent);color:#fff;}
29	
30	  /* ---------- layout ---------- */
31	  .main{display:grid;grid-template-columns:404px minmax(0,1fr);gap:14px;align-items:start;}
32	  .left,.right{display:flex;flex-direction:column;gap:12px;min-width:0;}
33	  .card{background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:0 1px 2px rgba(28,35,51,.05);}
34	  .card h2{font-size:11px;text-transform:uppercase;letter-spacing:1.2px;color:var(--muted);margin:0;padding:11px 14px 8px;font-weight:700;}
35	
36	  /* ---------- map ---------- */
37	  #map{display:block;width:100%;height:auto;border-radius:12px 12px 0 0;cursor:default;}
38	  .map-note{font-size:11px;color:var(--muted);padding:0 14px 10px;display:flex;gap:14px;flex-wrap:wrap;}
39	  .lg{display:inline-flex;align-items:center;gap:5px;}
40	  .lg i{width:14px;height:3px;border-radius:2px;display:inline-block;}
41	  .pin{cursor:pointer;}
42	  .pin:focus{outline:none;}
43	  .pin .hit{fill:transparent;}
44	  .pin.off{opacity:.28;filter:grayscale(1);}
45	  .pin.focus .focus-ring{display:block;}
46	  .focus-ring{display:none;fill:none;stroke:#f8fafc;stroke-width:2;stroke-dasharray:5 4;}
47	  .best-ring{fill:none;stroke:#fbbf24;stroke-width:2.5;opacity:.95;}
48	  .pin-letter{text-anchor:middle;fill:#0c1424;font-weight:800;font-size:13px;pointer-events:none;}
49	  .pin-name{text-anchor:middle;fill:#cbd5e1;font-size:11px;pointer-events:none;}
50	  .star-bg{fill:#fbbf24;}
51	  .star{text-anchor:middle;fill:#78350f;font-size:10px;pointer-events:none;}
52	
53	  /* ---------- chips ---------- */
54	  .chips{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 12px 12px;}
55	  .chip{display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--line);border-radius:10px;cursor:pointer;background:#fff;user-select:none;}
56	  .chip:hover{border-color:#d6cdbb;}
57	  .chip.focus{border-color:var(--accent);box-shadow:0 0 0 2px #fde68a;}
58	  .chip.off{opacity:.45;}
59	  .chip input{accent-color:var(--accent);margin:0;flex:none;}
60	  .dot{width:9px;height:9px;border-radius:50%;flex:none;display:inline-block;}
61	  .chip-name{min-width:0;line-height:1.25;}
62	  .chip-name b{display:block;font-size:12.5px;}
63	  .chip-name i{font-style:normal;font-size:10.5px;color:var(--muted);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
64	  .pill{margin-left:auto;font-weight:700;font-size:13px;font-variant-numeric:tabular-nums;color:var(--ink);}
65	
66	  /* ---------- weights ---------- */
67	  .presets{display:flex;gap:6px;padding:0 14px 10px;flex-wrap:wrap;}
68	  .pbtn{font-size:11.5px;border:1px solid var(--line);background:#faf9f5;border-radius:999px;padding:4px 11px;cursor:pointer;color:var(--ink);}
69	  .pbtn:hover{border-color:var(--accent);color:var(--accent);}
70	  .pbtn.on{background:var(--ink);border-color:var(--ink);color:#fff;}
71	  .wrow{display:grid;grid-template-columns:76px 1fr 28px 44px;gap:8px;align-items:center;padding:3px 14px;}
72	  .wlabel{font-size:12px;color:var(--ink);}
73	  .wrow input[type=range]{width:100%;accent-color:var(--accent);height:18px;margin:0;}
74	  .wval{font-size:12px;font-weight:700;text-align:right;font-variant-numeric:tabular-nums;}
75	  .wpct{font-size:10.5px;color:var(--muted);text-align:right;font-variant-numeric:tabular-nums;}
76	  .wfoot{font-size:10.5px;color:var(--muted);padding:6px 14px 10px;border-top:1px dashed var(--line);margin-top:6px;}
77	
78	  /* ---------- comparison table ---------- */
79	  .tblwrap{overflow:auto;max-height:664px;border-radius:0 0 12px 12px;}
80	  .tbl{display:grid;min-width:560px;}
81	  .trow{display:grid;grid-template-columns:132px repeat(4,minmax(0,1fr));border-top:1px solid var(--line);}
82	  .trow:first-child{border-top:none;}
83	  .trow>div{padding:6px 10px;min-width:0;}
84	  .tlab{color:var(--muted);font-size:11.5px;background:#faf9f5;display:flex;align-items:center;}
85	  .group-row>div{background:#efece3;font-weight:600;font-size:10.5px;letter-spacing:1px;color:#7c7468;padding:4px 10px;grid-column:1 / -1;}
86	  .thead{position:sticky;top:0;background:var(--card);z-index:2;box-shadow:0 1px 0 var(--line);}
87	  .cell{transition:background .12s;}
88	  .trow:not(.thead):not(.group-row):hover .cell{background:#f8f6f0;}
89	  .col{cursor:pointer;}
90	  .col.off{opacity:.35;filter:grayscale(.85);}
91	  .col.focus-col{background:#fffbeb;}
92	  .trow:not(.thead):not(.group-row):hover .col.focus-col{background:#fdf3d7;}
93	  .chead{display:flex;align-items:flex-start;gap:7px;}
94	  .chead .dot{margin-top:4px;}
95	  .cname{min-width:0;line-height:1.25;}
96	  .cname b{display:block;font-size:13px;white-space:nowrap;}
97	  .cname i{font-style:normal;font-size:10.5px;color:var(--muted);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
98	  .chead .pill{font-size:14px;margin-left:auto;}
99	  .pick{margin-top:5px;font-size:11px;border:1px solid var(--line);background:#fff;border-radius:6px;padding:2px 9px;cursor:pointer;color:var(--ink);}
100	  .pick:hover{border-color:var(--ink);}
101	  .pick.on{background:var(--ink);color:#fff;border-color:var(--ink);}
102	  .val{font-weight:600;font-size:12.5px;font-variant-numeric:tabular-nums;display:flex;gap:6px;align-items:baseline;flex-wrap:wrap;}
103	  .ctx{font-size:12px;color:#3f4756;}
104	  .btag{font-size:10px;font-weight:700;color:var(--good);border:1px solid currentColor;border-radius:4px;padding:0 4px;line-height:1.5;}
105	  .cellbest{background:#ecfdf5;}
106	  .trow:not(.thead):not(.group-row):hover .cellbest{background:#ddf7ec;}
107	  .bar{height:4px;border-radius:2px;background:#ece9e1;margin-top:5px;overflow:hidden;}
108	  .bar i{display:block;height:100%;border-radius:2px;}
109	
110	  /* ---------- verdict ---------- */
111	  .verdict{background:#111827;color:#e5e7eb;border-radius:12px;padding:12px 16px 11px;}
112	  .v-main{font-size:15.5px;display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;}
113	  .v-main b{font-size:17px;}
114	  .vscore{font-weight:800;font-size:17px;color:#fbbf24;font-variant-numeric:tabular-nums;}
115	  .vdelta{font-size:12px;color:#9ca3af;border:1px solid #374151;border-radius:6px;padding:1px 8px;}
116	  .v-sub{font-size:12px;color:#9ca3af;margin-top:5px;}
117	  .v-ticker{font-size:11px;color:#6b7280;margin-top:8px;padding-top:7px;border-top:1px dashed #374151;min-height:15px;}
118	  .v-clear{font-size:11px;background:transparent;border:1px solid #374151;color:#9ca3af;border-radius:6px;padding:1px 8px;cursor:pointer;margin-left:auto;}
119	  .v-clear:hover{border-color:#9ca3af;color:#e5e7eb;}
120	
121	  /* ---------- toast ---------- */
122	  #toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(12px);background:#111827;color:#fff;font-size:12.5px;padding:8px 16px;border-radius:999px;opacity:0;pointer-events:none;transition:all .2s;z-index:50;box-shadow:0 6px 20px rgba(0,0,0,.25);}
123	  #toast.show{opacity:1;transform:translateX(-50%) translateY(0);}
124	
125	  @media (max-width:1080px){
126	    .main{grid-template-columns:1fr;}
127	    .tblwrap{max-height:none;}
128	  }
129	</style>
130	</head>
131	<body>
132	<div class="app">
133	  <header>
134	    <div>
135	      <h1>落点 <em>PinDown</em> · 选址对比决策台</h1>
136	      <p class="sub">云洲市 · 12 人研发团队办公室 · 4 处候选并排比较 · 地图与决策输入同屏</p>
137	    </div>
138	    <div class="h-right">
139	      <span id="cmpCount">对比中 4/4</span>
140	      <button id="refreshBtn" title="模拟中介行情波动，租金小幅变动">模拟行情波动</button>
141	    </div>
142	  </header>
143	
144	  <div class="main">
145	    <!-- ======== 左列：地理语境 + 权重 ======== -->
146	    <div class="left">
147	      <div class="card">
148	        <h2>地理语境 · 云洲市轨道示意</h2>
149	        <svg id="map" viewBox="0 0 640 560" role="img" aria-label="云洲市示意图，标注 4 处候选场地">
150	          <rect width="640" height="560" fill="#0c1424"/>
151	          <g opacity="0.55" fill="#16203a">
152	            <rect x="70" y="70" width="150" height="100" rx="10"/>
153	            <rect x="255" y="95" width="115" height="85" rx="10"/>
154	            <rect x="415" y="150" width="145" height="105" rx="10"/>
155	            <rect x="95" y="330" width="125" height="105" rx="10"/>
156	            <rect x="420" y="330" width="150" height="85" rx="10"/>
157	          </g>
158	          <!-- 江 -->
159	          <path d="M -10 470 C 160 462 260 512 400 512 C 500 512 580 472 650 432" fill="none" stroke="#16436b" stroke-width="40" stroke-linecap="round"/>
160	          <path d="M -10 470 C 160 462 260 512 400 512 C 500 512 580 472 650 432" fill="none" stroke="#1e5c92" stroke-width="20" stroke-linecap="round" opacity=".85"/>
161	          <text x="520" y="548" fill="#3d6a96" font-size="11">云洲江</text>
162	          <!-- 环线 -->
163	          <rect x="70" y="58" width="500" height="410" rx="115" fill="none" stroke="#2c3a58" stroke-width="7"/>
164	          <text x="86" y="356" fill="#4a5878" font-size="10" transform="rotate(-90 86 356)">内环快速</text>
165	          <!-- 轨道 -->
166	          <path d="M 20 300 H 620" stroke="#eab308" stroke-width="4"/>
167	          <path d="M 210 20 V 540" stroke="#38bdf8" stroke-width="4"/>
168	          <path d="M 90 80 L 560 520" stroke="#f472b6" stroke-width="4"/>
169	          <text x="598" y="292" fill="#eab308" font-size="11" text-anchor="end">1 号线</text>
170	          <text x="222" y="34" fill="#38bdf8" font-size="11">4 号线</text>
171	          <text x="548" y="528" fill="#f472b6" font-size="11">7 号线</text>
172	          <!-- 换乘站 -->
173	          <g fill="#0c1424" stroke="#e2e8f0" stroke-width="2">
174	            <circle cx="210" cy="300" r="6"/>
175	            <circle cx="325" cy="300" r="6"/>
176	            <circle cx="210" cy="192" r="6"/>
177	          </g>
178	          <g fill="#94a3b8">
179	            <circle cx="110" cy="300" r="3.5"/><circle cx="390" cy="300" r="3.5"/><circle cx="480" cy="300" r="3.5"/>
180	            <circle cx="210" cy="100" r="3.5"/><circle cx="210" cy="400" r="3.5"/><circle cx="210" cy="500" r="3.5"/>
181	            <circle cx="146" cy="140" r="3.5"/><circle cx="412" cy="389" r="3.5"/>
182	          </g>
183	          <!-- 商圈标注 -->
184	          <g fill="#64748b" font-size="12" text-anchor="middle">
185	            <text x="300" y="252">老城 · 金融街</text>
186	            <text x="520" y="140">科技园</text>
187	            <text x="255" y="462">滨江带</text>
188	            <text x="128" y="52">站前商圈</text>
189	            <text x="80" y="528">大学城</text>
190	          </g>
191	          <g id="pins"></g>
192	        </svg>
193	        <div class="map-note">
194	          <span class="lg"><i style="background:#eab308"></i>1 号线</span>
195	          <span class="lg"><i style="background:#38bdf8"></i>4 号线</span>
196	          <span class="lg"><i style="background:#f472b6"></i>7 号线</span>
197	          <span class="lg"><i style="background:#fbbf24;height:8px;width:8px;border-radius:50%"></i>加权最优</span>
198	          <span>点击地标 / 表格列可聚焦</span>
199	        </div>
200	      </div>
201	
202	      <div class="card">
203	        <h2>比较清单 · 纳入 / 聚焦</h2>
204	        <div class="chips" id="chips"></div>
205	      </div>
206	
207	      <div class="card">
208	        <h2>决策权重 · 拖动即重算全表</h2>
209	        <div class="presets" id="presets"></div>
210	        <div id="wrows"></div>
211	        <div class="wfoot">权重为相对值，评分按总和归一 · 调整后右侧评分、排名、地标光环即时更新</div>
212	      </div>
213	    </div>
214	
215	    <!-- ======== 右列：对比面板 + 结论 ======== -->
216	    <div class="right">
217	      <div class="card">
218	        <h2>候选场地对比面板 · 4 列并排</h2>
219	        <div class="tblwrap"><div class="tbl" id="tbl"></div></div>
220	      </div>
221	
222	      <div class="verdict">
223	        <div class="v-main" id="vMain"></div>
224	        <div class="v-sub" id="vSub"></div>
225	        <div class="v-ticker" id="ticker"></div>
226	      </div>
227	    </div>
228	  </div>
229	</div>
230	<div id="toast"></div>
231	
232	<script>
233	/* ================= 数据（首屏内联，无任何加载态） ================= */
234	const CANDIDATES=[
235	  {id:'A',name:'中环大厦',district:'老城·金融街',color:'#f59e0b',addr:'中山北路 218 号 12F',
236	   rent:46800,area:260,floor:'12F / 24F',fitout:'带装修 · 家具全',fee:'32 ¥/㎡/月',deposit:'押三付一',
237	   free:'无',parking:'公共车位 0',register:'可注册',noise:68,quiet:3,commute:38,
238	   metro:10,metroText:'2 线 · 260m',amenity:9,note:'业主急租，免租期可谈',map:{x:250,y:285}},
239	  {id:'B',name:'创科广场',district:'科技园',color:'#10b981',addr:'科苑大道 88 号 6F',
240	   rent:35500,area:420,floor:'6F / 18F',fitout:'简装 · 需自购家具',fee:'24 ¥/㎡/月',deposit:'押二付一',
241	   free:'30 天',parking:'车位 6',register:'可注册',noise:44,quiet:8,commute:26,
242	   metro:7,metroText:'1 线 · 550m',amenity:7,note:'园区有人才公寓补贴',map:{x:505,y:250}},
243	  {id:'C',name:'江畔文创园',district:'滨江带',color:'#3b82f6',addr:'滨江东路 12 号 2F',
244	   rent:30000,area:520,floor:'2F / 3F',fitout:'loft · 保留装修',fee:'18 ¥/㎡/月',deposit:'押一付三',
245	   free:'45 天',parking:'车位 10',register:'需确认',noise:48,quiet:7,commute:47,
246	   metro:3,metroText:'1 线 · 1.1km',amenity:8,note:'园区班车接地铁站',map:{x:360,y:450}},
247	  {id:'D',name:'云锦中心',district:'站前商圈',color:'#a855f7',addr:'站前路 5 号 9F',
248	   rent:24000,area:200,floor:'9F / 30F',fitout:'带装修 · 部分家具',fee:'28 ¥/㎡/月',deposit:'押二付一',
249	   free:'无',parking:'公共车位 2',register:'可注册',noise:71,quiet:2,commute:33,
250	   metro:8,metroText:'2 线 · 450m',amenity:6,note:'低区可俯瞰站前广场',map:{x:165,y:125}}
251	];
252	
253	const CRITERIA=[
254	  {id:'rent',   label:'月租金',   lowerBetter:true,  def:25, get:c=>c.rent,    fmt:c=>'¥'+c.rent.toLocaleString('en-US')},
255	  {id:'commute',label:'通勤中位', lowerBetter:true,  def:25, get:c=>c.commute, fmt:c=>c.commute+' 分钟'},
256	  {id:'metro',  label:'轨交可达', lowerBetter:false, def:15, get:c=>c.metro,   fmt:c=>c.metro+' /10 · '+c.metroText},
257	  {id:'amenity',label:'周边配套', lowerBetter:false, def:15, get:c=>c.amenity, fmt:c=>c.amenity+' /10'},
258	  {id:'quiet',  label:'环境安静', lowerBetter:false, def:10, get:c=>c.quiet,   fmt:c=>c.quiet+' /10 · '+c.noise+' dB'},
259	  {id:'space',  label:'空间面积', lowerBetter:false, def:10, get:c=>c.area,    fmt:c=>c.area+' ㎡'}
260	];
261	
262	const CONTEXT=[
263	  {label:'商圈',    get:c=>c.district},
264	  {label:'地址',    get:c=>c.addr},
265	  {label:'楼层',    get:c=>c.floor},
266	  {label:'交付状态',get:c=>c.fitout},
267	  {label:'物业费',  get:c=>c.fee},
268	  {label:'押付方式',get:c=>c.deposit},
269	  {label:'免租期',  get:c=>c.free},
270	  {label:'车位',    get:c=>c.parking},
271	  {label:'工商注册',get:c=>c.register},
272	  {label:'房东备注',get:c=>c.note}
273	];
274	
275	const PRESETS={
276	  balance:{label:'均衡',     w:{rent:25,commute:25,metro:15,amenity:15,quiet:10,space:10}},
277	  cost:{   label:'成本优先', w:{rent:45,commute:15,metro:10,amenity:5, quiet:10,space:15}},
278	  commute:{label:'通勤优先', w:{rent:15,commute:45,metro:20,amenity:5, quiet:10,space:5}},
279	  exp:{    label:'体验优先', w:{rent:15,commute:15,metro:10,amenity:30,quiet:25,space:5}}
280	};
281	
282	/* ================= 状态 ================= */
283	const state={
284	  included:new Set(['A','B','C','D']),
285	  weights:Object.assign({},PRESETS.balance.w),
286	  preset:'balance',
287	  userPick:null,
288	  focus:null
289	};
290	let ticker=['09:30 行情快照 · 4 处候选均在租'];
291	
292	/* ================= 工具 ================= */
293	const $=s=>document.querySelector(s);
294	const byId=id=>CANDIDATES.find(c=>c.id===id);
295	
296	function computeScores(){
297	  const ids=[...state.included];
298	  const sumW=CRITERIA.reduce((s,c)=>s+state.weights[c.id],0);
299	  const res={};
300	  ids.forEach(id=>res[id]={total:0,per:{}});
301	  CRITERIA.forEach(crit=>{
302	    const vals=ids.map(id=>crit.get(byId(id)));
303	    const min=Math.min(...vals),max=Math.max(...vals);
304	    ids.forEach((id,i)=>{
305	      let n=(max-min)<1e-9?0.5:(crit.lowerBetter?1-(vals[i]-min)/(max-min):(vals[i]-min)/(max-min));
306	      if(sumW<1e-9)n=0;
307	      res[id].per[crit.id]=n*100;
308	      res[id].total+=n*state.weights[crit.id];
309	    });
310	  });
311	  if(sumW>1e-9)ids.forEach(id=>{res[id].total=res[id].total/sumW*100;});
312	  return res;
313	}
314	
315	function bestSetFor(crit,ids){
316	  const arr=ids.map(id=>({id,v:crit.get(byId(id))}));
317	  const bestV=crit.lowerBetter?Math.min(...arr.map(a=>a.v)):Math.max(...arr.map(a=>a.v));
318	  return arr.filter(a=>a.v===bestV).map(a=>a.id);
319	}
320	
321	function rankOf(critId,id){
322	  const crit=CRITERIA.find(x=>x.id===critId);
