function renderPins(){
  $('#pins').innerHTML=CANDIDATES.map(c=>{
    const inc=state.included.has(c.id);
    const isBest=inc&&bestId===c.id;
    return '<g class="pin'+(inc?'':' off')+(state.focus===c.id?' focus':'')+'" data-id="'+c.id+'" transform="translate('+c.map.x+','+c.map.y+')" tabindex="0" role="button" aria-label="'+c.name+'">'
      +(state.focus===c.id?'<circle r="22" class="focus-ring"/>':'')
      +(isBest?'<circle r="19" class="best-ring"/>':'')
      +'<circle r="13" style="fill:'+c.color+'"/>'
      +'<text class="pin-letter" dy="4.5">'+c.id+'</text>'
      +'<text class="pin-name" y="30">'+c.name+'</text>'
      +(isBest?'<g transform="translate(11,-11)"><circle r="8" class="star-bg"/><text class="star" dy="3.5">★</text></g>':'')
      +'<circle r="24" class="hit"/></g>';
  }).join('');
}

function renderVerdict(res,ranked){
  const vMain=$('#vMain'),vSub=$('#vSub');
  if(state.included.size<2){
    vMain.innerHTML='候选不足';
    vSub.textContent='请至少保留 2 个候选参与比较，比较本身即决策任务。';
  }else{
    const best=ranked[0],bc=byId(best.id),bs=res[best.id].total;
    if(!state.userPick){
      vMain.innerHTML='加权最优：<b style="color:'+bc.color+'">'+bc.name+'</b><span class="vscore">'+bs.toFixed(1)+'</span>'
        +'<button class="v-clear" id="vClear" hidden></button>';
      vSub.textContent='尚未锁定首选 · '+rationaleFor(best.id,res)+' · 在列头点「设为首选」锁定你的决定。';
    }else{
      const pc=byId(state.userPick),ps=res[state.userPick].total;
      const clearBtn='<button class="v-clear" id="vClear">清除锁定</button>';
      if(state.userPick===best.id){
        vMain.innerHTML='已锁定：<b style="color:'+pc.color+'">'+pc.name+'</b> ✓ 与加权评分一致<span class="vscore">'+ps.toFixed(1)+'</span>'+clearBtn;
        vSub.textContent=rationaleFor(state.userPick,res);
      }else{
        const diff=bs-ps;
        let wc=CRITERIA[0],wd=-1;
        CRITERIA.forEach(x=>{const d=res[best.id].per[x.id]-res[state.userPick].per[x.id];if(d>wd){wd=d;wc=x;}});
        vMain.innerHTML='已锁定：<b style="color:'+pc.color+'">'+pc.name+'</b><span class="vscore">'+ps.toFixed(1)+'</span>'
          +'<span class="vdelta">较加权最优 −'+diff.toFixed(1)+' 分</span>'+clearBtn;
        vSub.textContent='加权最优为 '+bc.name+'（'+bs.toFixed(1)+'）· 差距主要在「'+wc.label+'」 · '+rationaleFor(best.id,res);
      }
    }
  }
  const vc=$('#vClear');
  if(vc)vc.onclick=()=>{state.userPick=null;renderData();};
  $('#ticker').textContent=ticker.join('　·　');
}

function renderWeightValues(){
  document.querySelectorAll('#wrows input[data-k]').forEach(inp=>{
    const k=inp.dataset.k,w=state.weights[k];
    const row=inp.closest('.wrow');
    row.querySelector('.wval').textContent=w;
    const sum=CRITERIA.reduce((s,c)=>s+state.weights[c.id],0);
    row.querySelector('.wpct').textContent=sum>0?Math.round(w/sum*100)+'%':'—';
  });
  document.querySelectorAll('.pbtn').forEach(b=>{
    b.classList.toggle('on',b.dataset.preset===state.preset);
  });
}

function renderWeightsDOM(){
  $('#wrows').innerHTML=CRITERIA.map(c=>
    '<div class="wrow"><span class="wlabel">'+c.label+'</span>'
    +'<input type="range" min="0" max="50" step="5" value="'+state.weights[c.id]+'" data-k="'+c.id+'" aria-label="'+c.label+'权重">'
    +'<span class="wval">'+state.weights[c.id]+'</span><span class="wpct"></span></div>'
  ).join('');
  renderWeightValues();
}

function renderData(){
  const res=computeScores();
  const ranked=[...state.included].sort((a,b)=>res[b].total-res[a].total);
  bestId=ranked.length?ranked[0]:null;
  renderTable(res);

